// CV Page - PDF Download Functionality
(function() {
    'use strict';

    /**
     * Download CV as PDF
     * Captures the existing iframe that's already rendered on the page
     * Based on best practices for html2pdf with iframes
     */
    async function downloadAsPDF(event) {
        // Track file download attempt
        window.trackEvent('file_downloaded', {
            file_name: 'Zahara_Schaefer_CV.pdf',
            file_type: 'pdf',
            download_source: 'cv_page'
        });

        // Resolve button (event-based or fallback)
        let button = null;
        if (event && event.target) {
            button = event.target.closest('button') || event.target;
        } else {
            button = document.querySelector('button[onclick*="downloadAsPDF"]');
        }
        if (!button) {
            console.error('Download button not found');
            return;
        }

        const originalText = button.innerHTML;
        button.innerHTML = '<i class="fa fa-spinner fa-spin me-2"></i>Generating PDF...';
        button.disabled = true;

        try {
            console.log('Starting single-page PDF generation from iframe...');

            const iframe = document.querySelector('iframe[src="/downloads/Zahara_Schaefer.html"]');
            if (!iframe) {
                throw new Error('CV iframe not found on page');
            }

            // Wait for iframe load (same-origin only)
            await new Promise(resolve => {
                if (iframe.contentDocument && iframe.contentDocument.readyState === 'complete') {
                    resolve();
                } else {
                    iframe.onload = resolve;
                    setTimeout(resolve, 3000);
                }
            });

            await new Promise(resolve => setTimeout(resolve, 300));

            const iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
            const iframeBody = iframeDoc && iframeDoc.body;
            if (!iframeBody) {
                throw new Error('Iframe content not accessible (cross-origin or not loaded)');
            }

            if (!iframeBody.innerHTML || iframeBody.innerHTML.trim() === '') {
                throw new Error('Iframe content is empty');
            }

            const contentWidth = iframeBody.scrollWidth || iframeBody.offsetWidth;
            const contentHeight = iframeBody.scrollHeight || iframeBody.offsetHeight;
            const pdfHeightInches = contentHeight / 96; // Convert px to inches at 96 DPI

            console.log('Content dimensions:', {
                contentWidth,
                contentHeight,
                contentWidthInches: (contentWidth / 96).toFixed(2),
                pdfHeightInches: pdfHeightInches.toFixed(2),
                innerHTMLLength: iframeBody.innerHTML.length,
                textContentLength: iframeBody.textContent.length,
                first500Chars: iframeBody.textContent.substring(0, 500)
            });
            
            // Verify content is actually visible
            if (contentHeight === 0 || contentWidth === 0) {
                throw new Error('Content dimensions are zero - iframe may not be fully loaded');
            }

            const opt = {
                margin: 0.15,
                filename: 'Zahara_Schaefer_CV.pdf',
                pagebreak: { mode: [] }, 
                image: { type: 'jpeg', quality: 0.98 },
                html2canvas: {
                    scale: 1.5,
                    backgroundColor: '#ffffff',
                    useCORS: true, // Attempt to load images using CORS
                    allowTaint: false, // Don't allow cross-origin images to taint canvas
                    logging: true, // Enable logging to debug
                    letterRendering: true,
                    imageTimeout: 30000, // Increase timeout for image loading (30 seconds)
                    foreignObjectRendering: false, // Disable for better compatibility
                    removeContainer: true, // Cleanup cloned DOM elements
                    width: contentWidth, // Explicit width
                    height: contentHeight, // Explicit height
                    onclone: function(clonedDoc) {
                        console.log('onclone called');
                        const clonedBody = clonedDoc.body;
                        if (!clonedBody) {
                            console.error('Cloned body not found in onclone');
                            return;
                        }

                        console.log('Cloned body found, dimensions:', {
                            width: clonedBody.offsetWidth,
                            height: clonedBody.offsetHeight,
                            scrollWidth: clonedBody.scrollWidth,
                            scrollHeight: clonedBody.scrollHeight,
                            innerHTML: clonedBody.innerHTML.substring(0, 200),
                            textContent: clonedBody.textContent.substring(0, 200)
                        });

                        clonedDoc.documentElement.style.margin = '0';
                        clonedDoc.documentElement.style.padding = '0';

                        clonedBody.style.margin = '0';
                        clonedBody.style.padding = '0';
                        clonedBody.style.backgroundColor = '#ffffff';
                        clonedBody.style.visibility = 'visible';
                        clonedBody.style.opacity = '1';
                        clonedBody.style.display = 'block';

                        const firstChild = clonedBody.firstElementChild;
                        if (firstChild) {
                            firstChild.style.marginTop = '0';
                            firstChild.style.marginLeft = '0';
                            firstChild.style.marginRight = '0';
                            firstChild.style.visibility = 'visible';
                            firstChild.style.opacity = '1';
                        }

                        const header = clonedBody.querySelector('.resume-header');
                        if (header) {
                            header.style.backgroundColor = '#434E5E';
                            header.style.color = 'rgba(255, 255, 255, 0.9)';
                            header.style.printColorAdjust = 'exact';
                            header.style.webkitPrintColorAdjust = 'exact';
                            header.style.visibility = 'visible';
                            header.style.opacity = '1';
                        }

                        // Ensure all elements are visible
                        const allElements = clonedBody.querySelectorAll('*');
                        console.log('Found', allElements.length, 'elements in cloned body');
                        allElements.forEach(el => {
                            el.style.visibility = 'visible';
                            el.style.opacity = '1';
                            if (el.style.display === 'none') {
                                el.style.display = '';
                            }
                        });
                        
                        // Force a reflow
                        clonedBody.offsetHeight;
                    }
                },
                jsPDF: {
                    unit: 'in',
                    format: [8.5, pdfHeightInches], // Custom page size: 8.5in wide × calculated height
                    orientation: 'portrait',
                    compress: true
                }
            };

            await html2pdf().set(opt).from(iframeBody).save();
            console.log('Single-page PDF generation complete');

        } catch (error) {
            console.error('PDF generation failed:', error);
            alert(
                'Error generating PDF: ' +
                error.message +
                '.'
            );
        } finally {
            button.innerHTML = originalText;
            button.disabled = false;
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.downloadAsPDF = downloadAsPDF;
    });
})();
